CREATE OR REPLACE FUNCTION __FQ__.estimator_catalog(p_category STRING DEFAULT NULL)
RETURNS TABLE(category_id STRING, category STRING, product_id STRING, product STRING, engine STRING,
              entrypoints STRING, implementation_state STRING, validation_state STRING, use_when STRING,
              required_facts STRING, pricing_basis STRING, region_scope STRING, status_note STRING,
              evidence_ref STRING, catalog_as_of STRING)
COMMENT 'Estimator coverage catalog for discovery and routing. Omit p_category to list all categories and products; optionally pass a category id such as COMPUTE or SQL. The catalog distinguishes implementation from validation, documents pricing basis, and is not a price source or a calculator.'
RETURN
  SELECT category_id, category, product_id, product, engine, entrypoints, implementation_state, validation_state,
         use_when, required_facts, pricing_basis, region_scope, status_note, evidence_ref, catalog_as_of
  FROM VALUES
  (10, 'COMPUTE', 'Compute and cluster sizing', 'DCP_PROCESSING', 'Workload processing estimate', 'DCP_CALCULATOR', 'dcp_calc_totals, dcp_calc_line_items, dcp_calc_details', 'AVAILABLE', 'PARTIAL', 'DCP workload cost by workload type, run time/frequency, or a named DCP use case; accept prose or request JSON.', 'Workload type and the applicable runtime/run details; calculator defaults are disclosed; workload volume is not a DCP processing input.', 'DCP rate card; Databricks account prices where present, otherwise explicit REFERENCE_ONLY/PENDING statuses; AWS registry rates by status. No rate substitution.', 'DCP registry currently covers US_EAST_1.', 'Includes CONTINUOUS_STREAMING, EVENT_DRIVEN_BATCH, SCHEDULED_BATCH, ML_TRAINING and BATCH_SCORING. Some compute choices, including GPU jobs and serverless pipelines, can remain PENDING.', 'Workbook A2-A8, B9-B11, C; Oct 28 Genie benchmark. Partial: selected workloads only; Q13 first-turn area gate failed in the latest full run.', '2026-10-29'),
